# R golden fixtures for gaply_core's ordinary least squares linear regression
# as an analysis (Research OS, Phase 9A-1, decisions 669 and 671, capability
# stats.analyze.linear_regression).
#
# Run by its full path, from anywhere:
#
#   /usr/local/bin/Rscript make_linear_regression_fixtures.R
#
# R is the reference, run outside Gaply (ADR-008): nothing of R is copied into
# Gaply. Base R only (stats): lm, summary.lm, anova, confint, pf, cor, fitted,
# resid, mean, sd. Written with R 4.6.1, whose version the files' headers
# record.
#
# Writes, next to this script:
#   * data_*.csv: one synthetic dataset per case (a two-line '#' header, then
#     `id,` and the columns), each number %.17g of R's own double, so the file
#     names that double exactly; every number below comes from R's in-memory
#     doubles, never from text R parsed back;
#   * cases.tsv: each case's file ("-" for a case the test builds by the formula
#     below), its outcome's header, its predictors' headers in the list's order
#     ("-" for none) and its missing codes;
#   * expected.tsv: R's answer for every case, one number per row (case, key,
#     value), the value as %.17g; "nc <code>" for a number Gaply gives as not
#     computable; for a refusal, the code and its parameters.
#
# Where each number comes from:
#   * lm(y ~ x1 + ... + xk) on the complete rows in the file's order, and
#     summary.lm: the coefficients, their standard errors, t and p, sigma, R^2,
#     adjusted R^2, F and its df; anova(fit): the sums of squares, the regression
#     SS the sum of its sequential rows; confint(fit): the 95% intervals;
#     pf(F, k, df, lower.tail = FALSE): F's p; cor(x, y): the zero-order
#     correlations; fitted and resid; mean and sd;
#   * WRITTEN BY A DIFFERENT ROUTE FROM GAPLY'S (decision 671): each standardized
#     coefficient as coef * sd(x) / sd(y); each VIF as 1 / (1 - R^2) of
#     lm(x_j ~ the other predictors), tolerance its inverse; each partial
#     correlation as cor(resid(lm(y ~ others)), resid(lm(x_j ~ others))), each
#     part correlation as cor(y, resid(lm(x_j ~ others))); the Durbin-Watson
#     statistic as sum(diff(e)^2) / sum(e^2); the standardized residuals e / sigma;
#     the standardized predicted values scale(fitted);
#   * the note: whether summary.lm warned "essentially perfect fit";
#   * a refusal: Gaply's checks in decision 669's order, decided here from the
#     values; predictors_collinear on the first predictor lm gives NA;
#     fit_out_of_range where a sum of squares is not finite.
#
# A row is used only when the outcome and every predictor have a number that is
# not a ticked code; a row left out is counted once, under the first column
# without one, the outcome first.
#
# The two 100,000-row cases are built by a formula identical in R and in the
# test, from integer arithmetic and one division per column:
#   x_j(i) = ((i * A_j) %% M_j) / D_j and
#   y(i) = (sum_j C_j ((i * A_j) %% M_j) + (i * 104729) %% 10007) / 100,
# i from 0 to 99,999, with A_j the j-th prime from 101, M_j = 1009 + 2 j,
# D_j = 10 + j and C_j = (j %% 7) - 3 (j from 1).
#
# Synthetic data only. No manuscript or data of anyone's is read.

here <- local({
  a <- commandArgs(trailingOnly = FALSE)
  f <- sub("^--file=", "", a[grep("^--file=", a)])
  if (length(f)) dirname(normalizePath(f)) else getwd()
})
setwd(here)

HEADER <- c(
  "# Synthetic data for gaply_core's linear regression R golden fixtures (Research OS, Phase 9A-1).",
  "# Generated by /usr/local/bin/Rscript make_linear_regression_fixtures.R (do not edit by hand)."
)
fmt <- function(x) if (is.character(x)) x else if (is.na(x)) "NA" else sprintf("%.17g", x)
f17 <- function(x) ifelse(is.na(x), "", sprintf("%.17g", x))
P <- "stats.linear_regression."
NC <- function(code) paste0("nc ", P, code)

cases <- character()
expected <- character()
emit <- function(case, key, value) {
  expected <<- c(expected, paste(case, key, fmt(value), sep = "\t"))
}
add_case <- function(case, file, outcome, predictors, codes) {
  cases <<- c(cases, paste(case, file, outcome,
                           if (length(predictors)) paste(predictors, collapse = " ") else "-",
                           if (length(codes)) paste(vapply(codes, fmt, ""), collapse = " ") else "-",
                           sep = "\t"))
}

# A data file of numeric columns, NA written empty; character columns pass as
# written. The rows are shuffled once by a fixed permutation, then that order is
# the file's.
write_data <- function(name, m, shuffle = TRUE) {
  n <- nrow(m)
  o <- if (shuffle) order((seq_len(n) * 7919) %% 10007, seq_len(n)) else seq_len(n)
  m <- m[o, , drop = FALSE]
  cols <- lapply(seq_len(ncol(m)), function(j) if (is.character(m[, j])) m[, j] else f17(m[, j]))
  writeLines(c(HEADER, paste(c("id", colnames(m)), collapse = ","),
               do.call(paste, c(list(seq_len(n)), cols, sep = ","))),
             paste0("data_", name, ".csv"), useBytes = TRUE)
  invisible(m)
}

# The analysis of data frame `d`: outcome column `yname`, predictors `xnames`
# in the list's order, `codes` ticked. Every number from R's doubles.
analyse <- function(case, d, yname, xnames, codes = numeric()) {
  all <- c(yname, xnames)
  k <- length(xnames)
  m <- as.matrix(d[, all, drop = FALSE])
  value <- !is.na(m)
  coded <- value & (m %in% codes)
  dim(coded) <- dim(m)
  good <- value & !coded
  used <- rowSums(good) == ncol(m)
  missing <- numeric(ncol(m)); code <- numeric(ncol(m))
  for (r in which(!used)) {
    j <- which(!good[r, ])[1]
    if (value[r, j]) code[j] <- code[j] + 1 else missing[j] <- missing[j] + 1
  }
  for (j in seq_along(all)) {
    emit(case, sprintf("excluded.%d.missing_value", j - 1), missing[j])
    emit(case, sprintf("excluded.%d.missing_code", j - 1), code[j])
  }
  cm <- m[used, , drop = FALSE]
  y <- cm[, 1]
  X <- cm[, -1, drop = FALSE]
  n <- nrow(cm)
  emit(case, "rows_used", n)
  for (j in seq_along(all)) {
    emit(case, sprintf("column.%d.mean", j - 1), mean(cm[, j]))
    emit(case, sprintf("column.%d.sd", j - 1), sd(cm[, j]))
  }
  df <- data.frame(cm)
  names(df) <- c("y", paste0("x", seq_len(k)))
  form <- as.formula(paste("y ~", paste(paste0("x", seq_len(k)), collapse = " + ")))
  perfect_warned <- FALSE
  fit <- lm(form, data = df)
  s <- withCallingHandlers(summary(fit), warning = function(w) {
    if (grepl("essentially perfect fit", conditionMessage(w))) perfect_warned <<- TRUE
    invokeRestart("muffleWarning")
  })
  stopifnot(!any(is.na(coef(fit))))
  co <- s$coefficients
  ci <- confint(fit)
  e <- resid(fit)
  f <- fitted(fit)
  rdf <- fit$df.residual
  av <- anova(fit)
  ss_reg <- sum(av[["Sum Sq"]][seq_len(k)])
  ss_res <- av[["Sum Sq"]][k + 1]
  fstat <- s$fstatistic
  emit(case, "model.r_squared", s$r.squared)
  emit(case, "model.r", sqrt(s$r.squared))
  emit(case, "model.adjusted_r_squared", s$adj.r.squared)
  emit(case, "model.standard_error_of_estimate", s$sigma)
  emit(case, "model.durbin_watson", sum(diff(e)^2) / sum(e^2))
  emit(case, "anova.regression.sum_of_squares", ss_reg)
  emit(case, "anova.regression.df", k)
  emit(case, "anova.regression.mean_square", ss_reg / k)
  emit(case, "anova.residual.sum_of_squares", ss_res)
  emit(case, "anova.residual.df", rdf)
  emit(case, "anova.residual.mean_square", av[["Mean Sq"]][k + 1])
  emit(case, "anova.total.sum_of_squares", ss_reg + ss_res)
  emit(case, "anova.total.df", n - 1)
  emit(case, "anova.f", fstat[["value"]])
  emit(case, "anova.p", pf(fstat[["value"]], fstat[["numdf"]], fstat[["dendf"]], lower.tail = FALSE))
  names_out <- c("b", "standard_error", "t", "p")
  for (i in 1:4) emit(case, paste0("intercept.", names_out[i]), co[1, i])
  emit(case, "intercept.lower", ci[1, 1])
  emit(case, "intercept.upper", ci[1, 2])
  for (j in seq_len(k)) {
    key <- function(s) sprintf("predictor.%d.%s", j - 1, s)
    for (i in 1:4) emit(case, key(names_out[i]), co[j + 1, i])
    emit(case, key("lower"), ci[j + 1, 1])
    emit(case, key("upper"), ci[j + 1, 2])
    xj <- X[, j]
    emit(case, key("beta"), co[j + 1, 1] * sd(xj) / sd(y))
    emit(case, key("zero_order"), cor(xj, y))
    others <- X[, -j, drop = FALSE]
    if (k == 1) {
      ry <- y - mean(y)
      rx <- xj - mean(xj)
      vif <- 1
    } else {
      ry <- resid(lm(y ~ others))
      rx <- resid(lm(xj ~ others))
      vif <- 1 / (1 - summary(lm(xj ~ others))$r.squared)
    }
    emit(case, key("partial"), cor(ry, rx))
    emit(case, key("part"), cor(y, rx))
    emit(case, key("vif"), vif)
    emit(case, key("tolerance"), 1 / vif)
  }
  emit(case, "residuals.predicted.minimum", min(f))
  emit(case, "residuals.predicted.maximum", max(f))
  emit(case, "residuals.predicted.mean", mean(f))
  emit(case, "residuals.predicted.standard_deviation", sd(f))
  emit(case, "residuals.residual.minimum", min(e))
  emit(case, "residuals.residual.maximum", max(e))
  emit(case, "residuals.residual.mean", mean(e))
  emit(case, "residuals.residual.standard_deviation", sd(e))
  zf <- (f - mean(f)) / sd(f)
  emit(case, "residuals.standardized_predicted.minimum", min(zf))
  emit(case, "residuals.standardized_predicted.maximum", max(zf))
  emit(case, "residuals.standardized_residual.minimum", min(e / s$sigma))
  emit(case, "residuals.standardized_residual.maximum", max(e / s$sigma))
  emit(case, "note.essentially_perfect_fit", as.numeric(perfect_warned))
  invisible(fit)
}

refuse <- function(case, code, params = list()) {
  emit(case, "refused", paste0(P, code))
  for (p in names(params)) emit(case, paste0("refused.", p), params[[p]])
}

run <- function(case, d, yname, xnames, codes = numeric(), shuffle = TRUE) {
  d2 <- write_data(case, d, shuffle)
  add_case(case, paste0("data_", case, ".csv"), yname, xnames, codes)
  analyse(case, as.data.frame(d2), yname, xnames, codes)
}

set.seed(966969)
mk <- function(n, k, b, noise, gen = function(n) round(rnorm(n, 0, 3), 2)) {
  X <- sapply(seq_len(k), function(j) gen(n))
  if (k == 1) X <- matrix(X, ncol = 1)
  y <- round(as.vector(1.5 + X %*% b + rnorm(n, 0, noise)), 3)
  m <- cbind(y = y, X)
  colnames(m) <- c("y", paste0("x", seq_len(k)))
  invisible(m)
}

# One predictor, small.
run("one_small", mk(10, 1, 0.8, 1.2), "y", "x1")
# Three predictors, small, negative values among them, a header outside ASCII.
m3 <- mk(15, 3, c(0.5, -1.25, 2), 1.5)
colnames(m3)[3] <- "x_üß"
run("three_small", m3, "y", c("x1", "x_üß", "x3"))
# The same three predictors in another order.
run("three_permuted", m3, "y", c("x3", "x1", "x_üß"))
# The same data with the rows in another order (a second shuffle).
m3r <- m3[order((seq_len(15) * 37) %% 17), , drop = FALSE]
run("three_rows_reordered", m3r, "y", c("x1", "x_üß", "x3"))

# Offsets: an outcome near 1e8 with a small spread, predictors near 1e6, each
# predictor's sd / |mean| at 1e-5 or more.
n <- 40
xo1 <- 1e6 + round(runif(n, 0, 100), 3)
xo2 <- -2e6 + round(runif(n, 0, 150), 3)
yo <- 1e8 + round(3 * (xo1 - 1e6) - 0.5 * (xo2 + 2e6) + rnorm(n, 0, 20), 2)
run("offsets", cbind(y = yo, x1 = xo1, x2 = xo2), "y", c("x1", "x2"))
# A predictor whose sd / |mean| lies between 2e-7 and 5e-7: R fits it; the
# tolerance mutation's red case.
xt <- 1e6 + round(runif(n, 0, 1.2), 4)
xt2 <- round(rnorm(n, 0, 2), 3)
yt <- round(5 + 4 * (xt - 1e6) + xt2 + rnorm(n, 0, 0.3), 4)
stopifnot(sd(xt) / abs(mean(xt)) > 2e-7, sd(xt) / abs(mean(xt)) < 5e-7)
run("tolerance", cbind(y = yt, x1 = xt, x2 = xt2), "y", c("x1", "x2"))
# Values near 1e-8.
xs1 <- rnorm(25, 0, 1) * 1e-8
xs2 <- rnorm(25, 0, 1) * 1e-8
ys <- (0.3 + 2 * xs1 / 1e-8 - xs2 / 1e-8 + rnorm(25, 0, 0.5)) * 1e-8
run("tiny", cbind(y = ys, x1 = xs1, x2 = xs2), "y", c("x1", "x2"))
# Predictors correlated at .999 and at .99999.
for (r in c(0.999, 0.99999)) {
  z1 <- rnorm(50)
  z2 <- r * z1 + sqrt(1 - r^2) * rnorm(50)
  yc <- 1 + z1 + 0.5 * z2 + rnorm(50, 0, 0.5)
  run(sprintf("correlated_%s", sub("0\\.", "", format(r))), cbind(y = yc, x1 = z1, x2 = z2), "y", c("x1", "x2"))
}
# 50 predictors on 60 rows.
m50 <- mk(60, 50, rnorm(50, 0, 0.3), 1, gen = function(n) rnorm(n))
run("p50_n60", m50, "y", paste0("x", 1:50))
# An essentially perfect fit: y exactly linear in x on paper, rounding apart.
xe <- seq(0.1, 2.0, by = 0.1)
ye <- 0.1 + 0.3 * xe
ye2 <- round(rnorm(20), 2)
run("essentially_perfect", cbind(y = ye, x1 = xe, x2 = ye2), "y", c("x1", "x2"))
# Missing values and codes in each column, listwise.
mm <- mk(30, 2, c(1, -0.5), 1)
mm[c(2, 9), "y"] <- NA
mm[c(4), "y"] <- -99
mm[c(5, 11), "x1"] <- NA
mm[c(13, 14, 15), "x1"] <- -99
mm[c(17), "x2"] <- NA
mm[c(20, 21), "x2"] <- -99
mm[c(23), c("y", "x1")] <- NA
mm[c(25), c("x1", "x2")] <- -99
run("missing", mm, "y", c("x1", "x2"), codes = c(-99))

# The 100,000-row cases, by the formula in the header; no data file.
big <- function(k) {
  i <- 0:99999
  primes <- c()
  p <- 101
  while (length(primes) < k) {
    if (all(p %% 2:floor(sqrt(p)) != 0)) primes <- c(primes, p)
    p <- p + 1
  }
  ints <- sapply(seq_len(k), function(j) (i * primes[j]) %% (1009 + 2 * j))
  X <- sapply(seq_len(k), function(j) ints[, j] / (10 + j))
  cj <- (seq_len(k) %% 7) - 3
  y <- (as.vector(ints %*% cj) + (i * 104729) %% 10007) / 100
  m <- cbind(y = y, X)
  colnames(m) <- c("y", paste0("x", seq_len(k)))
  invisible(m)
}
for (k in c(3, 49)) {
  case <- sprintf("big_%d", k)
  add_case(case, "-", "y", paste0("x", seq_len(k)), numeric())
  analyse(case, as.data.frame(big(k)), "y", paste0("x", seq_len(k)))
}

