# Collinear predictors, refused on the predictor R gives NA.
collinear <- function(case, m, xnames) {
  d2 <- write_data(case, m)
  add_case(case, paste0("data_", case, ".csv"), "y", xnames, numeric())
  df <- as.data.frame(d2[, c("y", xnames)])
  names(df) <- c("y", paste0("v", seq_along(xnames)))
  fit <- lm(as.formula(paste("y ~", paste(paste0("v", seq_along(xnames)), collapse = " + "))), data = df)
  na <- which(is.na(coef(fit)[-1]))
  stopifnot(length(na) >= 1)
  refuse(case, "predictors_collinear", list(column = xnames[na[1]]))
}
cs <- mk(20, 3, c(1, 2, 0.5), 1)
cs <- cbind(cs, x4 = cs[, "x1"] + cs[, "x2"])
collinear("refuse_collinear_sum", cs, c("x1", "x2", "x4", "x3"))
cmul <- mk(20, 2, c(1, -1), 1)
cmul <- cbind(cmul, x3 = 3 * cmul[, "x1"])
collinear("refuse_collinear_multiple", cmul, c("x1", "x2", "x3"))

# Values whose sums of squares overflow a double.
big_m <- base * 1e200
stopifnot(!is.finite(sum((big_m[, "y"] - mean(big_m[, "y"]))^2)))
write_data("refuse_overflow", big_m)
add_case("refuse_fit_out_of_range", "data_refuse_overflow.csv", "y", c("x1", "x2"), numeric())
refuse("refuse_fit_out_of_range", "fit_out_of_range")

stamp <- c("# written by: /usr/local/bin/Rscript make_linear_regression_fixtures.R",
           paste0("# ", R.version.string, ", base R stats only"))
writeLines(c(stamp, "case\tfile\toutcome\tpredictors\tmissing_codes", cases), "cases.tsv", useBytes = TRUE)
writeLines(c(stamp, "case\tkey\tvalue", expected), "expected.tsv", useBytes = TRUE)
cat(sprintf("%d cases, %d expected values\n", length(cases), length(expected)))
